    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def comps(inp):
    H,W=len(inp),len(inp[0]); seen=[[False]*W for _ in range(H)]; objs=[]
    for i in range(H):
        for j in range(W):
            if inp[i][j]!=0 and not seen[i][j]:
                v=inp[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and inp[x][y]==v:
                            seen[x][y]=True; stack.append((x,y))
                objs.append((v,frozenset(cells)))
    return objs
def f(inp):
    H,W=len(inp),len(inp[0])
    objs=comps(inp)
    # order: size desc, then color asc (consistent with both demos)
    objs.sort(key=lambda vc:(-len(vc[1]), vc[0]))
    occ=set(); out=[[0]*W for _ in range(H)]
    for v,cells in objs:
        c0=min(b for a,b in cells); c1=max(b for a,b in cells)
        cells=[(a,c0+c1-b) for a,b in cells]          # horizontal mirror within bbox
        cur=cells[:]
        while True:
            nxt=[(a,b+1) for a,b in cur]
            if any(b>=W for _,b in nxt): break
            if any(p in occ for p in nxt): break
            ok=True
            for a,b in nxt:
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    if (a+da,b+db) in occ: ok=False; break
                if not ok: break
            if not ok: break
            occ.update(nxt); cur=nxt
        for a,b in cur: out[a][b]=v
    return out
